import * as T from './vendor/three.module.js';
const wrap=a=>T.MathUtils.euclideanModulo(a+Math.PI,2*Math.PI)-Math.PI;
// Authored orbit: preserve the camera's roll and revolve around its focus point.
export class RoomOrbit {
 constructor(camera,settings){this.camera=camera;this.settings=settings;camera.updateWorldMatrix(true,false);const q=camera.getWorldQuaternion(new T.Quaternion()),position=camera.getWorldPosition(new T.Vector3()),back=new T.Vector3(0,0,1).applyQuaternion(q),up=new T.Vector3(0,1,0).applyQuaternion(q),projected=new T.Vector3(0,1,0).projectOnPlane(back);this.roll=projected.angleTo(up)*(projected.clone().cross(up).dot(back)>=0?1:-1);this.target=position.clone().addScaledVector(back,-(camera.userData.record?.current.targetOffset??1000));this.spherical=new T.Spherical().setFromVector3(position.sub(this.target));const v=settings.rotationVerticalOffset??{min:Math.PI,max:Math.PI},h=settings.rotationHorizontalOffset??{min:Math.PI,max:Math.PI};this.minPhi=wrap(this.spherical.phi-v.min);this.maxPhi=wrap(this.spherical.phi+v.max);this.minTheta=wrap(this.spherical.theta-h.min);this.maxTheta=wrap(this.spherical.theta+h.max);this.phiFree=v.min===Math.PI&&v.max===Math.PI;this.thetaFree=h.min===Math.PI&&h.max===Math.PI;}
 move(dx,dy,height){if(!height||!this.settings.enableRotate)return;const delta=new T.Vector2(dx,dy).rotateAround(new T.Vector2(),-this.roll).multiplyScalar(-2*Math.PI/height*(this.settings.enableDamping?.2:1));const mode=this.settings.rotationLimitsMode??0,soft=this.settings.rotationSoftLimit??0;
 const limit=(d,current,min,max,free,flipped=false)=>{if(free)return d;current=wrap(current)+(soft===0?d:0);let over=0;if(flipped){if(current>max&&current<0)over=max-current;else if(current<min&&current>0)over=min-current;}else if(current>max)over=max-current;else if(current<min)over=min-current;over=wrap(over);if(soft===0)return d+over;let ratio=Math.min(Math.abs(over/(Math.PI/4)),1);if(soft===1)ratio=1-(1-ratio)**4;return d*over<0?d*(1-ratio):d;};
 if(mode===2||mode===3)delta.x=limit(delta.x,this.spherical.theta,this.minTheta,this.maxTheta,this.thetaFree,this.minTheta>this.maxTheta);if(mode===1||mode===3)delta.y=limit(delta.y,this.spherical.phi,this.minPhi,this.maxPhi,this.phiFree);if(mode!==2)this.spherical.phi+=delta.y;if(mode!==1)this.spherical.theta+=delta.x;
 const camera=this.camera,offset=new T.Vector3().setFromSpherical(this.spherical),position=this.target.clone().add(offset),up=new T.Vector3(0,1,0).applyAxisAngle(offset.clone().normalize(),this.roll),phi=this.spherical.phi%(2*Math.PI);if(phi>Math.PI||phi<0&&phi>-Math.PI)up.negate();const worldQ=new T.Quaternion().setFromRotationMatrix(new T.Matrix4().lookAt(position,this.target,up));const parent=camera.parent?.matrixWorld??new T.Matrix4();camera.position.copy(position).applyMatrix4(parent.clone().invert());camera.quaternion.copy(new T.Quaternion().setFromRotationMatrix(parent.clone().extractRotation(parent)).invert().multiply(worldQ));camera.updateMatrix();const hidden=camera.userData.record?.current.hiddenMatrix;if(hidden)camera.matrix.premultiply(new T.Matrix4().fromArray(hidden));camera.matrixWorldNeedsUpdate=true;camera.updateWorldMatrix(false,false);
 }
}
